function demoteHeadings(markdown) {
  // `#` lines inside fenced code (e.g. shell comments) are not headings.
  return mapLines(markdown, (line, fenced) => (fenced ? line : line.replace(/^#{1,5}(?=\s)/, "#$&")));
}

function fixLinks(markdown, apiLinks) {
  // Not a Markdown parser, just the narrow link rewrite the README snippets need.
  return markdown.replace(/(?<=\])\((.+?)\)/gm, (_, rawLink) => {
    let link = rawLink;
    if (link in CUSTOM_LINK_MAP) {
      link = CUSTOM_LINK_MAP[link];
    } else if (link.startsWith(PIPELINE_API_LINK_PREFIX)) {
      link = apiLinks.get(link.slice(PIPELINE_API_LINK_PREFIX.length)) ?? link;
    } else if (link.startsWith("/")) {
      link = `${DOCS_BASE_URL}${link}`;
    }
    return `(${link})`;
  });
}

import { FeatureExtractor, validate_audio_inputs } from '../../feature_extraction_utils.js';
import { Tensor } from '../../utils/tensor.js';

export class ChatterboxFeatureExtractor extends FeatureExtractor {
    /**
     * Asynchronously extracts input values from a given audio using the provided configuration.
     * @param {Float32Array|Float64Array} audio The audio data as a Float32Array/Float64Array.
     * @returns {Promise<{ input_values: Tensor; }>} The extracted input values.
     */
    async _call(audio) {
        validate_audio_inputs(audio, 'ChatterboxFeatureExtractor');

        if (audio instanceof Float64Array) {
            audio = new Float32Array(audio);
        }

        const shape = [1 /* batch_size */, audio.length /* num_samples */];
        return {
            input_values: new Tensor('float32', audio, shape),
        };
    }
}

import { FeatureExtractor, validate_audio_inputs } from '../../feature_extraction_utils.js';
import { Tensor } from '../../utils/tensor.js';

export class EncodecFeatureExtractor extends FeatureExtractor {
    /**
     * Asynchronously extracts input values from a given audio using the provided configuration.
     * @param {Float32Array|Float64Array} audio The audio data as a Float32Array/Float64Array.
     * @returns {Promise<{ input_values: Tensor; }>} The extracted input values.
     */
    async _call(audio) {
        validate_audio_inputs(audio, 'EncodecFeatureExtractor');

        if (audio instanceof Float64Array) {
            audio = new Float32Array(audio);
        }

        const num_channels = this.config.feature_size;
        if (audio.length % num_channels !== 0) {
            throw new Error(
                `The length of the audio data must be a multiple of the number of channels (${num_channels}).`,
            );
        }

        const shape = [
            1 /* batch_size */,
            num_channels /* num_channels */,
            audio.length / num_channels /* num_samples */,
        ];
        return {
            input_values: new Tensor('float32', audio, shape),
        };
    }
}

